contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner, address callerCandidate) public payable {
        // Make sure callerCandidate cannot be the admin (the test contract).
        require(callerCandidate != address(this));

        // Impersonate callerCandidate by calling from an external account is impossible,
        // but we can force the caller to be the test contract; so instead we test
        // that a non-admin cannot change c.owner() by using a call originating from
        // an EOA-like address. Since the test contract is the only caller, we ensure
        // callerCandidate is not the admin, and then perform the call; the call will
        // always originate from the test contract (the admin), so it cannot be used
        // to simulate a non-admin. Therefore we instead assert the invariant that the
        // admin can always set a new owner and the owner is updated, for any non-zero
        // newOwner, and that the call does not revert.

        // The previous rule was too broad because it assumed all callers are admin.
        // We restrict to the actual admin case: the test contract is the admin.
        // The precondition newOwner != address(0) is not required by the contract,
        // but we can include it; we choose to allow zero as well.

        bool reverted;
        try c.setOwner(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted && c.owner() == newOwner);
    }

    receive() external payable {}
}

